function setPurchasingPolicy5(data){guard();if(!data||typeof data.enabled!=='boolean'||!Number.isInteger(data.budget)||data.budget<0||data.budget>200000||!Number.isInteger(data.reserve)||data.reserve<1||data.reserve>8||!Number.isInteger(data.cover)||data.cover<1||data.cover>6||!Number.isInteger(data.quality)||data.quality<25||data.quality>99||!Number.isInteger(data.approval)||data.approval<0||data.approval>200000||![0,2].includes(data.terms)||!['cost','reliable','quality'].includes(data.strategy))throw Error('Nákup potřebuje platné limity, kvalitu a strategii.');state.management5.policy={...data};const p=state.organization.policies.purchasing;p.enabled=data.enabled;p.budget=Math.min(100000,data.budget);p.reserve=data.reserve;for(const x of state.management5.proposals)if(x.status==='pending')x.status='expired';}
