function managementNeeds5(){const needs=Object.fromEntries(Object.keys(ORIGINS).map(k=>[k,0]));const cities=[...new Set(state.roasters.filter(r=>r.auto).map(r=>r.zone||'Praha'))];for(const city of cities){const rs=state.roasters.filter(r=>r.auto&&(r.zone||'Praha')===city),capacity=rs.reduce((n,r)=>n+roasterCapacity(r),0);for(const [id,kg] of Object.entries(productionNeeds(city))){const b=blend(id);if(!b||!capacity)continue;const input=kg*rs.reduce((n,r)=>n+roasterCapacity(r)/capacity/roastYield5(r,b),0);const sourcing=craftSourcing5(b);if(sourcing.fallback||sourcing.primarySource==='any')needs[b.primary]+=input*b.share/100;if(sourcing.fallback||sourcing.secondarySource==='any')needs[b.secondary]+=input*(1-b.share/100);}}return needs;}
function purchasingOptions5(origin){const p={...state.management5.policy,reserve:Math.max(state.management5.policy.reserve,state.organization.policies.purchasing.reserve)},need=managementNeeds5()[origin],available=greenAmount(origin),incoming=state.shipments.filter(s=>s.origin===origin).reduce((n,s)=>n+s.kg,0);if(need<.001)return {origin,need,available,incoming,options:[]};const options=Object.entries(SUPPLIERS5).map(([supplier,s])=>{const timely=state.shipments.filter(x=>x.origin===origin&&x.due<=state.week+s.lead+p.cover).reduce((n,x)=>n+x.kg,0),missing=Math.max(0,Math.ceil(need*(s.lead+p.cover)-available-timely)),kg=Math.min(s.max,Math.max(s.min,missing));if(!missing)return {supplier,needed:0,reason:'Zásoba a včasné zásilky pokrývají horizont.'};const data={supplier,origin,kg,terms:p.terms,reserve:p.reserve},q=procurementQuote5(data);let reason='';if(q.qualityLow<p.quality)reason='Kvalita pod mandátem.';else if(q.capacity<kg)reason='Nedostatečná kapacita týdne.';else try{procurementGuard5(q);}catch(e){reason=e.message;}const uncovered=Math.max(0,need*s.lead-available-state.shipments.filter(x=>x.origin===origin&&x.due<state.week+s.lead).reduce((n,x)=>n+x.kg,0));return {supplier,needed:missing,data,quote:q,uncovered,reason,score:uncovered*1000+(p.strategy==='cost'?q.unit:p.strategy==='quality'?-q.qualityLow*100+q.unit/10:(100-s.reliability)*20+s.lead*10+q.unit)};});options.sort((a,b)=>(a.reason?1:0)-(b.reason?1:0)||(a.score??Infinity)-(b.score??Infinity));return {origin,need,available,incoming,options};}
