function decideManagementPurchase5(id,approve){guard();const x=state.management5.proposals.find(x=>x.id===id&&x.status==='pending');if(!x||typeof approve!=='boolean')throw Error('Návrh už není aktuální.');if(!approve){x.status='rejected';return;}const e=state.organization.executives.purchasing,p=state.management5.policy;if(x.week!==state.week||!e.manager||e.manager.pid!==x.pid||!p.enabled||!state.organization.policies.purchasing.enabled||!state.departments.sales)throw Error('Mandát nebo autor návrhu se změnil.');const current=purchasingOptions5(x.data.origin).options.find(o=>!o.reason&&o.quote);if(!current||JSON.stringify(current.data)!==JSON.stringify(x.data)||JSON.stringify(current.quote)!==JSON.stringify(x.quote))throw Error('Potřeba nebo mandát se změnily. Aktualizuj nabídku.');const q=procurementQuote5(x.data);if(JSON.stringify(q)!==JSON.stringify(x.quote))throw Error('Cena, hotovost nebo kapacita se změnila. Nech připravit nový návrh.');const o=bookManagementPurchase5(x.data,q,'Zakladatel · schváleno pro '+x.name,x.reason);x.status='approved';x.order=o.id;}
function refreshManagementProposal5(id){guard();const x=state.management5.proposals.find(x=>x.id===id&&x.status==='pending'),e=state.organization.executives.purchasing,p=state.management5.policy;if(!x||!e.manager||e.manager.pid!==x.pid||!p.enabled||!state.organization.policies.purchasing.enabled||!state.departments.sales)throw Error('Návrh nemá platného autora a mandát.');const plan=purchasingOptions5(x.data.origin),best=plan.options.find(o=>!o.reason&&o.quote);if(!best)throw Error('Zásoba je pokrytá nebo žádný dodavatel nevyhovuje.');x.week=state.week;x.data=best.data;x.quote=best.quote;x.reason='Aktuální potřeba '+managementNumber5(plan.need,1)+' kg/týden, sklad '+managementNumber5(plan.available,1)+' kg, na cestě '+managementNumber5(plan.incoming,1)+' kg. Vyžaduje schválení částky '+money(best.quote.cost)+'.';return x;}
function runPurchasing5(){const m=state.management5,p=m.policy,e=state.organization.executives.purchasing,mandate=state.organization.policies.purchasing,report=state.organization.reports.find(r=>r.role==='purchasing');for(const x of m.proposals)if(x.status==='pending'&&x.week<state.week-1)x.status='expired';if(!e.manager||!p.enabled||!mandate.enabled||!state.departments.sales){if(report)report.text=!state.departments.sales?'Nákup potřebuje pracovníka Obchodu.':'Automatický nákup není povolen.';return;}const spent=managementSpent5();let booked=0,proposed=0,held=0;for(const origin of Object.keys(ORIGINS)){const plan=purchasingOptions5(origin),best=plan.options.find(x=>!x.reason&&x.quote);if(!best){if(plan.options.some(x=>x.needed)){held++;}continue;}const q=best.quote,reason='Potřeba výroby '+managementNumber5(plan.need,1)+' kg/týden; sklad '+managementNumber5(plan.available,1)+' kg, na cestě '+managementNumber5(plan.incoming,1)+' kg. Strategie '+({cost:'cena',reliable:'spolehlivost',quality:'kvalita'})[p.strategy]+'.'+(best.uncovered>0?' Před příjezdem hrozí nedostatek; ověř expres nebo výrobu.':'');if(q.cost>p.approval||spent.total+q.cost>p.budget||spent.total+q.cost>mandate.budget){if(!m.proposals.some(x=>x.status==='pending'&&x.data.origin===origin)){m.proposals.push({id:uid('approval'),week:state.week,pid:e.manager.pid,name:e.manager.name,data:best.data,quote:q,reason,status:'pending',order:null});proposed++;}continue;}try{bookManagementPurchase5(best.data,q,e.manager.name,reason);booked++;}catch(error){held++;}}
 m.proposals=m.proposals.slice(-40);if(report){report.status=booked?'done':'held';report.cost=spent.total;report.text=booked+' objednávek, '+proposed+' nových návrhů ke schválení, '+held+' původů bez vhodného nákupu. Limit '+money(Math.min(p.budget,mandate.budget))+', rezerva '+p.reserve+' týdnů.';if(booked)state.organization.history.unshift({...report});state.organization.history=state.organization.history.slice(0,120);}}
