function managerApply5(s,a){if(a.kind==='price'){s.price+=a.value;shiftMenu(s,a.value);s.menuStats=menuSummary(s);s.price=clamp(round(s.menuStats.price),40,400);s.menuAnchor=s.price;}else if(a.kind==='marketing')s.marketing=a.value;else if(a.kind==='shifts'){s.daily.shifts=[...a.value];planCrew5(s);}}
function managerEstimate5(id,action={kind:'hold'}){const original=state,trace=supplyTrace5;try{state=JSON.parse(JSON.stringify(original));supplyTrace5=null;const s=state.stores.find(s=>s.id===id);managerApply5(s,action);const d=demandForStore(s,state.event?.factor||1),summary=d.menu||menuSummary(s),served=d.potential,coffee=state.batches.filter(b=>b.blend===s.blend&&(b.zone===loc(id).city||state.deliveryPolicy==='express')),kg=coffee.reduce((n,b)=>n+b.kg,0),unit=kg?coffee.reduce((n,b)=>n+b.cost*b.kg,0)/kg:(recipe(blend(s.blend)).cost+55)/.84,price=summary.price+(d.foodRevenue||0),cost=served*((d.ingredientCost??13)+(d.dose||.018)*unit)+s.staff*s.wage+(d.shiftWageAdjustment||0)+(s.manager?.salary||0)+premisesCost5(s)+3200+s.marketing+(d.extraCosts||0);return {profit:served*price-cost,served,quality:s.quality,lost:Math.max(0,d.demand-served),wait:d.service5.days.reduce((n,x)=>n+x.wait*x.served,0)/Math.max(1,served)};}finally{state=original;supplyTrace5=trace;}}
autoManager=function(s){const p=s.management5||managerPolicy5();if(!p.enabled||s.franchise)return MANAGEMENT_BASE5.autoManager(s);store3(s);if(s.price!==s.menuAnchor)shiftMenu(s,s.price-s.menuAnchor);s.menuStats=menuSummary(s);s.price=clamp(round(s.menuStats.price),40,400);s.menuAnchor=s.price;const owner=owner5(s);if(!owner?.automatic){planCrew5(s);return ['Chytré řízení čeká na obsazenou roli s aktivní pravomocí.'];}const baseline=managerEstimate5(s.id),actions=[{kind:'hold',label:'Beze změny'}];if(s.auto.price)for(const value of [-5,5])if(s.price+value>=40&&s.price+value<=350)actions.push({kind:'price',value,label:'Cena '+(value>0?'+':'')+value+' Kč'});if(s.auto.marketing)for(const value of [Math.max(0,s.marketing-500),Math.min(p.budget,s.budget,10000,s.marketing+500)])if(value!==s.marketing&&state.cash-Math.max(0,value-s.marketing)-state.procurement5.payables.filter(x=>x.paid===null&&x.due<=state.week+2).reduce((n,x)=>n+x.amount,0)>=(weeklyFixed()+Math.max(0,value-s.marketing))*p.reserve)actions.push({kind:'marketing',value,label:'Marketing '+money(value)+'/týden'});if(s.auto.staff&&s.daily.auto&&!s.crew?.manual){const value=suggestShifts5(s);if(value.join('/')!==s.daily.shifts.join('/'))actions.push({kind:'shifts',value,label:'Směny '+value.join(' / ')});}
 const score=r=>p.goal==='service'?r.served*20+r.profit*.02:p.goal==='quality'?r.quality*100+r.profit*.02:r.profit,options=actions.map(a=>({action:a,estimate:a.kind==='hold'?baseline:managerEstimate5(s.id,a)}));options.sort((a,b)=>score(b.estimate)-score(a.estimate));const best=options[0],delta=best.estimate.profit-baseline.profit;let action=best.action;if(score(best.estimate)-score(baseline)<1)action=actions[0];managerApply5(s,action);planCrew5(s);const reason='Cíl '+({profit:'zisk',service:'obsluha',quality:'kvalita'})[p.goal]+'. Porovnáno '+options.length+' povolených variant; odhad předpokládá dostatek kávy.',row=managementRecord5({options:options.map(x=>({action:x.action.label,...x.estimate})),kind:'store',target:s.id,author:owner.person.name,action:action.label,reason,cost:0,expected:action.kind==='hold'?baseline:best.estimate,baseline,actual:null,changed:action.kind!=='hold'});return [owner.person.name+': '+action.label+'. '+reason+(row.changed?' Odhad změny výsledku '+money(delta)+'/týden.':'')];};
