function managementScore5(h){const stores=state.stores.filter(s=>!s.franchise&&s.last),served=stores.reduce((n,s)=>n+s.last.served,0),lost=stores.reduce((n,s)=>n+s.last.lost,0),quality=served?stores.reduce((n,s)=>n+s.last.quality*s.last.served,0)/served:null,values={profit:h.profit,quality,reserve:weeklyFixed()?Math.max(0,state.cash)/weeklyFixed():0,stores:state.stores.length,lost:served+lost?lost/(served+lost):null},goals={...state.management5.goals},checks={profit:values.profit>=goals.profit,quality:quality!==null&&quality>=goals.quality,reserve:values.reserve>=goals.reserve,stores:values.stores>=goals.stores,lost:values.lost!==null&&values.lost<=goals.lost};return {week:h.week,goals,values,checks,achieved:Object.values(checks).filter(Boolean).length};}
proposal=function(type){const p=MANAGEMENT_BASE5.proposal(type),m=state.management5,h=m.history.at(-1);if(!m.boardEnabled||!h)return p;const goals=m.goals,cost=type==='roastery'?180000:type==='dividend'?100000:0,reserve=Math.max(0,state.cash-cost)/Math.max(1,weeklyFixed());if(reserve<goals.reserve||p.avg<goals.profit){p.votes[0].yes=false;p.votes[0].reason='Mandát boardu: rezerva po návrhu '+managementNumber5(reserve,1)+' / '+goals.reserve+' týdnů, průměrný výsledek '+money(p.avg)+' / '+money(goals.profit)+'.';}if(h.values.quality===null||h.values.quality<goals.quality){p.votes[2].yes=false;p.votes[2].reason='Mandát boardu: skutečná kvalita obsloužených '+(h.values.quality===null?'není dostupná':managementNumber5(h.values.quality,1))+' / cíl '+goals.quality+'.';}if(type==='expansion'&&(h.values.lost===null||h.values.lost>goals.lost)){p.votes[1].yes=false;p.votes[1].reason='Mandát boardu: před růstem naprav obsluhu, limit neobsloužených '+managementNumber5(goals.lost*100)+' %.';}p.passed=p.votes.filter(v=>v.yes).length>=2;return p;};
