nextWeek=function(){guard();ensureManagement5(state);const h=MANAGEMENT_BASE5.nextWeek(),m=state.management5;for(const row of m.decisions){if(row.actual)continue;if(row.kind==='store'&&row.week===h.week){const s=state.stores.find(s=>s.id===row.target);row.actual=s?.last?{week:h.week,profit:s.last.profit,served:s.last.served,quality:s.last.quality,lost:s.last.lost,wait:s.operations?.wait||0}:null;}else if(row.kind==='purchase'){const o=state.procurement5.orders.find(o=>o.id===row.target);if(o?.received!==null&&o)row.actual={week:o.received,kg:o.kg,quality:o.quality,due:o.due,onTime:o.received<=o.expected};}else if(row.kind==='director'&&row.week===h.week)row.actual={week:h.week,profit:h.profit};}for(const x of m.proposals.filter(x=>x.status==='pending')){try{refreshManagementProposal5(x.id);}catch{x.status='expired';}}const score=managementScore5(h);m.history.push(score);m.history=m.history.slice(-26);const rows=m.decisions.filter(r=>r.week===h.week),records=state.performance5.at(-1).records;records.push({kind:'governance',id:'board',name:'Board a vedení firmy',scope:'Pět měřitelných cílů',owner:'Zakladatel / board',issue:score.achieved+' z 5 cílů splněno. Výsledek firmy není důkazem přínosu jednotlivého zásahu.',severity:score.achieved<3?2:score.achieved<5?1:0,values:{achieved:score.achieved,profit:h.profit,quality:score.values.quality,reserve:score.values.reserve,lost:score.values.lost,decisions:rows.filter(r=>r.kind==='purchase'||r.kind==='director'||r.changed).length,committed:rows.reduce((n,r)=>n+r.cost,0)}});return h;};
function managementExceptions5(){const alerts=[],add=(severity,target,text,view,id='')=>alerts.push({severity,target,text,view,id});if(!state.stores.length)add(1,'První kavárna','Vyber adresu a otevři první provoz.','city');const m=state.management5,p=m.policy;if(p.enabled&&(!state.organization.executives.purchasing.manager||!state.departments.sales))add(2,'Nákup','Mandát je zapnutý, ale chybí ředitel nebo pracovník Obchodu.','organization');for(const x of m.proposals.filter(x=>x.status==='pending'))add(1,'Nákup · '+ORIGINS[x.data.origin].name,'Schválení '+money(x.quote.cost)+': '+x.reason,'management',x.id);for(const bill of state.procurement5.payables.filter(x=>x.paid===null&&x.due<=state.week))add(2,SUPPLIERS5[bill.supplier].name,'Splatná faktura '+money(bill.amount)+'.','procurement');for(const o of state.procurement5.orders.filter(o=>o.status==='delayed'))add(1,SUPPLIERS5[o.supplier].name,'Zpožděných '+o.kg+' kg, příjezd T'+o.due+'.','procurement');if(p.enabled&&state.organization.executives.purchasing.manager)for(const origin of Object.keys(ORIGINS)){const plan=purchasingOptions5(origin);if(plan.need&&plan.available<plan.need)add(2,ORIGINS[origin].name,'Méně než týden zelených zrn. Prověř příjezdy, expres nebo výrobu.','supply');if(plan.options.some(x=>x.needed)&&!plan.options.some(x=>x.quote&&!x.reason))add(1,ORIGINS[origin].name,'Žádný nákup nesplňuje kvalitu, kapacitu nebo rezervu.','management');}for(const s of state.stores.filter(s=>!s.franchise)){if(s.management5.enabled&&!owner5(s)?.automatic)add(1,loc(s.id).name,'Chytré řízení nemá obsazenou roli s aktivním mandátem.','organization');if(s.last?.stockLost>0)add(2,loc(s.id).name,s.last.stockLost+' hostů bez kávy; prověř výrobu a trasu.','supply');else if(s.last&&s.last.lost/Math.max(1,s.last.served+s.last.lost)>.2)add(1,loc(s.id).name,'Více než pětina hostů neobsloužena; prověř směny a místa.','live',s.id);if(s.last?.profit<0)add(1,loc(s.id).name,'Ztráta '+money(s.last.profit)+'; prověř cenu a náklady.','stores',s.id);}return alerts.sort((a,b)=>b.severity-a.severity);}
validateSave=function(input){if(input?.version===5&&input.organization&&Array.isArray(input.stores))ensureManagement5(input);const v=MANAGEMENT_BASE5.validateSave(input);ensureManagement5(v);const m=v.management5,fail=()=>{throw Error('Soubor obsahuje neplatné mandáty nebo výsledky vedení.');},n=(x,a=0,b=1e12)=>Number.isFinite(x)&&x>=a&&x<=b,integer=(x,a,b)=>Number.isInteger(x)&&n(x,a,b),text=(x,max=1500)=>typeof x==='string'&&x.length<=max,id=x=>text(x,60)&&/^[a-z0-9-]{1,60}$/.test(x),week=x=>integer(x,1,v.week),p=m?.policy,g=m?.goals;if(typeof m?.boardEnabled!=='boolean'||!p||typeof p.enabled!=='boolean'||!integer(p.budget,0,200000)||!integer(p.reserve,1,8)||!integer(p.cover,1,6)||!integer(p.quality,25,99)||!integer(p.approval,0,200000)||![0,2].includes(p.terms)||!['cost','reliable','quality'].includes(p.strategy)||!g||!integer(g.profit,0,10000000)||!integer(g.quality,25,99)||!integer(g.reserve,1,8)||!integer(g.stores,1,LOCATIONS.length)||!n(g.lost,0,1)||!m.spent||!week(m.spent.week)||!n(m.spent.total)||!['proposals','decisions','history'].every(k=>Array.isArray(m[k]))||m.proposals.length>40||m.decisions.length>300||m.history.length>26)fail();for(const k of ['proposals','decisions'])if(new Set(m[k].map(x=>x.id)).size!==m[k].length)fail();for(const s of v.stores){const p=s.management5;if(typeof m?.boardEnabled!=='boolean'||!p||typeof p.enabled!=='boolean'||!integer(p.budget,0,10000)||!integer(p.reserve,1,8)||!['profit','service','quality'].includes(p.goal))fail();}
 for(const x of m.proposals){const q=x.quote,d=x.data;if(!id(x.id)||!week(x.week)||!id(x.pid)||!text(x.name,60)||!text(x.reason)||!['pending','approved','rejected','expired'].includes(x.status)||x.order!==null&&!id(x.order)||!d||!Object.hasOwn(SUPPLIERS5,d.supplier)||!Object.hasOwn(ORIGINS,d.origin)||!integer(d.kg,SUPPLIERS5[d.supplier].min,SUPPLIERS5[d.supplier].max)||![0,2].includes(d.terms)||!integer(d.reserve,1,8)||!q||q.week!==x.week||q.supplier!==d.supplier||q.origin!==d.origin||q.kg!==d.kg||q.terms!==d.terms||q.reserve!==d.reserve||!n(q.unit,1,5000)||!n(q.cost,1)||Math.abs(q.cost-q.unit*q.kg)>.011||!n(q.cash,-1e12)||!integer(q.due,x.week+1,1000100)||!integer(q.qualityLow,25,99)||!integer(q.qualityHigh,q.qualityLow,99)||!n(q.capacity,0,2500)||!n(q.reliability,0,100)||q.contract!==false||q.weeks!==0||q.fee!==0)fail();}
 for(const r of m.decisions){if(!id(r.id)||!week(r.week)||!['purchase','store','director'].includes(r.kind)||!id(r.target)||!text(r.author,160)||!text(r.action)||!text(r.reason)||!n(r.cost)||r.changed!==undefined&&typeof r.changed!=='boolean')fail();if(r.options!==undefined&&(!Array.isArray(r.options)||r.options.length>8||r.options.some(o=>!text(o.action,80)||!['profit','served','quality','lost','wait'].every(k=>n(o[k],k==='profit'?-1e12:0)))))fail();const metric=(o,keys)=>o&&keys.every(k=>n(o[k],k==='profit'?-1e12:0));if(r.kind==='store'&&(!metric(r.expected,['profit','served','quality','lost','wait'])||!metric(r.baseline,['profit','served','quality','lost','wait'])||r.actual!==null&&(!week(r.actual.week)||!metric(r.actual,['profit','served','quality','lost','wait']))))fail();if(r.kind==='purchase'&&(!r.expected||!n(r.expected.kg,1,2500)||!integer(r.expected.due,r.week+1,1000100)||!n(r.expected.quality,25,99)||r.actual!==null&&(!week(r.actual.week)||!n(r.actual.kg,1,2500)||!n(r.actual.quality,25,99)||typeof r.actual.onTime!=='boolean')))fail();if(r.kind==='director'&&(r.expected!==null||r.actual!==null&&(!week(r.actual.week)||!n(r.actual.profit,-1e12))))fail();}
 let previous=0;for(const h of m.history){if(!week(h.week)||h.week>=v.week||h.week<=previous||!h.goals||!h.values||!h.checks||!integer(h.achieved,0,5))fail();previous=h.week;if(Object.keys(h.goals).length!==5||Object.keys(h.values).length!==5||Object.keys(h.checks).length!==5||!integer(h.goals.profit,0,10000000)||!integer(h.goals.quality,25,99)||!integer(h.goals.reserve,1,8)||!integer(h.goals.stores,1,LOCATIONS.length)||!n(h.goals.lost,0,1)||!n(h.values.profit,-1e12)||h.values.quality!==null&&!n(h.values.quality,25,99)||!n(h.values.reserve)||!integer(h.values.stores,0,LOCATIONS.length)||h.values.lost!==null&&!n(h.values.lost,0,1))fail();for(const k of ['profit','quality','reserve','stores','lost'])if(typeof h.checks[k]!=='boolean'||h.checks[k]!== (h.values[k]!==null&&(k==='lost'?h.values[k]<=h.goals[k]:h.values[k]>=h.goals[k])))fail();if(h.achieved!==Object.values(h.checks).filter(Boolean).length)fail();}return v;};
